<style>
    .info-page{--ip-ink:#171923;--ip-muted:#686d79;--ip-line:#e6e7ea;--ip-soft:#f5f5f3;color:var(--ip-ink);background:#fff;overflow:hidden}.info-page,.info-page *{box-sizing:border-box}.info-page__container{width:min(1120px,calc(100% - 40px));margin-inline:auto}.info-page__hero{padding:62px 0 68px;background:radial-gradient(circle at 88% 15%,rgba(0,0,0,.07),transparent 25%),linear-gradient(135deg,#f8f8f6,#eeefec)}.info-page__crumbs{display:flex;align-items:center;gap:9px;margin-bottom:20px;color:var(--ip-muted);font-size:14px}.info-page__crumbs a{color:inherit;text-decoration:none}.info-page__crumbs a:hover{color:#000}.info-page__crumbs span{opacity:.5}.info-page__hero h1{max-width:820px;margin:0;font-size:clamp(36px,5.5vw,64px);font-weight:700;letter-spacing:-.045em;line-height:1}.info-page__hero p{max-width:640px;margin:20px 0 0;color:var(--ip-muted);font-size:17px;line-height:1.7}.info-page__body{padding:64px 0 82px}.info-page__card{padding:clamp(25px,5vw,58px);border:1px solid var(--ip-line);border-radius:20px;background:#fff;box-shadow:0 18px 55px rgba(26,28,35,.07)}.info-page__content{color:#3f434d;font-size:16px;line-height:1.85;overflow-wrap:anywhere}.info-page__content>:first-child{margin-top:0!important}.info-page__content>:last-child{margin-bottom:0!important}.info-page__content h1,.info-page__content h2,.info-page__content h3,.info-page__content h4,.info-page__content h5,.info-page__content h6{margin:34px 0 14px;color:var(--ip-ink);font-weight:700;letter-spacing:-.025em;line-height:1.3}.info-page__content h1,.info-page__content h2{font-size:clamp(25px,3vw,36px)}.info-page__content h3{font-size:22px}.info-page__content h4{font-size:19px}.info-page__content p{margin:0 0 19px}.info-page__content ul,.info-page__content ol{margin:14px 0 25px;padding-left:24px}.info-page__content li{margin:9px 0;padding-left:5px}.info-page__content strong{color:var(--ip-ink)}.info-page__content a{color:var(--ip-ink);text-decoration:underline}.info-page__content img{height:auto!important;max-width:100%!important;border-radius:12px}.info-page__content table{display:block;width:100%!important;max-width:100%;overflow-x:auto;border-collapse:collapse}.info-page__content iframe{width:100%;max-width:100%}.info-page__lead{display:flex;align-items:center;gap:12px;margin:0 0 26px;color:#747883;font-size:12px;font-weight:700;letter-spacing:.15em;text-transform:uppercase}.info-page__lead:before{width:34px;height:2px;background:#222;content:""}
    .info-page__empty{padding:70px 24px;text-align:center}.info-page__empty-icon{display:grid;width:68px;height:68px;margin:0 auto 22px;border-radius:50%;background:var(--ip-soft);place-items:center;font-size:28px}.info-page__empty h2{margin:0 0 10px;font-size:27px}.info-page__empty p{max-width:500px;margin:0 auto;color:var(--ip-muted);line-height:1.7}
    .info-page__faq-list{display:grid;gap:13px}.info-page__faq{border:1px solid var(--ip-line);border-radius:14px;background:#fff;overflow:hidden;transition:border-color .2s,box-shadow .2s}.info-page__faq[open]{border-color:#cfd1d6;box-shadow:0 12px 32px rgba(26,28,35,.06)}.info-page__faq summary{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:22px 24px;color:var(--ip-ink);font-size:17px;font-weight:700;line-height:1.45;list-style:none;cursor:pointer}.info-page__faq summary::-webkit-details-marker{display:none}.info-page__faq summary:after{display:grid;flex:0 0 34px;height:34px;border-radius:50%;background:var(--ip-soft);content:"+";font-size:22px;font-weight:400;place-items:center;transition:transform .2s}.info-page__faq[open] summary:after{content:"−";transform:rotate(180deg)}.info-page__faq-answer{padding:0 70px 23px 24px;color:var(--ip-muted);font-size:15px;line-height:1.75}.info-page__faq-answer>:first-child{margin-top:0}.info-page__faq-answer>:last-child{margin-bottom:0}.info-page__faq-answer img{height:auto;max-width:100%}.info-page__faq-answer a{color:var(--ip-ink);text-decoration:underline}
    .info-page__contact-grid{display:grid;grid-template-columns:minmax(260px,.72fr) minmax(0,1.28fr);gap:26px;align-items:start}.info-page__contact-card{padding:32px;border:1px solid var(--ip-line);border-radius:18px;background:#fff;box-shadow:0 14px 40px rgba(26,28,35,.06)}.info-page__contact-card h2{margin:0 0 10px;font-size:27px}.info-page__contact-card>p{margin:0 0 28px;color:var(--ip-muted);line-height:1.65}.info-page__detail{display:flex;gap:14px;padding:18px 0;border-top:1px solid var(--ip-line)}.info-page__detail-icon{display:grid;flex:0 0 42px;height:42px;border-radius:50%;background:var(--ip-soft);place-items:center}.info-page__detail small{display:block;margin-bottom:4px;color:#858994;font-size:11px;font-weight:700;letter-spacing:.1em;text-transform:uppercase}.info-page__detail a,.info-page__detail div{color:var(--ip-ink);text-decoration:none;line-height:1.55}.info-page__form-grid{display:grid;grid-template-columns:1fr 1fr;gap:17px}.info-page__field--wide{grid-column:1/-1}.info-page__field label{display:block;margin-bottom:8px;font-size:13px;font-weight:600}.info-page__field input,.info-page__field textarea{width:100%;border:1px solid #dcdde2;border-radius:9px;background:#fafafa;padding:14px 15px;color:var(--ip-ink);font:inherit;outline:none;transition:.2s}.info-page__field textarea{min-height:145px;resize:vertical}.info-page__field input:focus,.info-page__field textarea:focus{border-color:#222;background:#fff;box-shadow:0 0 0 3px rgba(0,0,0,.06)}.info-page__button{display:inline-flex;align-items:center;justify-content:center;min-height:48px;margin-top:20px;border:1px solid #1d1e22;border-radius:8px;background:#1d1e22;padding:0 25px;color:#fff;font-weight:700;cursor:pointer}.info-page__button:hover{background:#fff;color:#1d1e22}.info-page__map{height:420px;margin-top:28px;border-radius:18px;overflow:hidden}.info-page__map iframe{width:100%;height:100%;border:0}
    @media(max-width:800px){.info-page__hero{padding:48px 0 52px}.info-page__body{padding:44px 0 58px}.info-page__contact-grid{grid-template-columns:1fr}.info-page__map{height:340px}}
    @media(max-width:575px){.info-page__container{width:min(100% - 28px,1120px)}.info-page__hero{padding:36px 0 40px}.info-page__hero p{font-size:15px}.info-page__body{padding:32px 0 46px}.info-page__card,.info-page__contact-card{padding:22px;border-radius:14px}.info-page__content{font-size:15px;line-height:1.75}.info-page__faq summary{padding:18px;font-size:15px}.info-page__faq-answer{padding:0 18px 19px;font-size:14px}.info-page__form-grid{grid-template-columns:1fr}.info-page__field--wide{grid-column:auto}.info-page__button{width:100%}.info-page__map{height:285px;border-radius:14px}}
</style>
